#[target_feature(enable = "avx512f")]
fn test_x86_avx512f_mm256_mask_rolv_epi64_vs_unmasked_impl() -> Result<Verdict, String> {
    unsafe {
        let a = create__m256i_from_i32_array([1, 2, 3, 4, 5, 6, 7, 8]);
        let b = create__m256i_from_i32_array([9, 10, 11, 12, 13, 14, 15, 16]);
        let src = create__m256i_from_i32_array([17, 18, 19, 20, 21, 22, 23, 24]);
        let k = create__mmask8_from(0b01010101);
        let masked = unpack__m256i_to_i64_array(_mm256_mask_rolv_epi64(src, k, a, b));
        let plain = unpack__m256i_to_i64_array(_mm256_rolv_epi64(a, b));
        let src_lanes = unpack__m256i_to_i64_array(src);
        let expected: [i64; 4] = core::array::from_fn(|i| if (k >> i) & 1 == 1 { plain[i] } else { src_lanes[i] });
        check_array_equality(&masked, &expected).map_err(|e| crate::cpu::with_call(e, "_mm256_mask_rolv_epi64(src, k, a, b) vs _mm256_rolv_epi64(a, b)"))?;
        Ok(Verdict::Checked)
    }
}

